var CAT_RULES=[['Drinks',/\b(juice|soda|water|coke|pepsi|sorrel|punch|drink|beer|smoothie|coffee|tea|shake|ginger beer|mauby|coconut)\b/i],['Dessert',/\b(cake|ice cream|brownie|pudding|dessert|sweet|cookie|pie|flan)\b/i],['Pizza',/\bpizza|calzone/i],['Roti',/\broti|dhalpuri|dhal puri|paratha|buss ?up ?shut|wrap\b/i],['Doubles',/\bdoubles\b/i],['Seafood',/\b(shrimp|fish|shark|crab|lobster|calamari|seafood|salmon|kingfish|prawn)\b/i],['Breakfast',/\b(breakfast|egg|omelet|omelette|pancake|sausage bake|bake & saltfish|saltfish)\b/i],['Chicken',/\b(chicken|wings?|nuggets?|tenders?)\b/i],['Beef',/\b(beef|burger|steak|smash|patty|bacon|goat|ribs?)\b/i],['Sides',/\b(fries|sides?|salad|rice|coleslaw|plantain|corn|onion rings|chow)\b/i]];
function categorize(name){for(var i=0;i<CAT_RULES.length;i++){if(CAT_RULES[i][1].test(name||''))return CAT_RULES[i][0]}return 'Other'}
function parseMenuText(raw,opts){opts=opts||{};var text=String(raw||'').replace(/\u00A0/g,' ').replace(/TT\s*\$/gi,'$').replace(/\bTTD?\s*(?=\d)/gi,'$').replace(/\$\s+(?=\d)/g,'$');if(opts.ocr)text=text.replace(/(^|\s)S(\d{2,3})(?!\d)/g,'$1$$$2');var items=[],seen={},ctx=null,skipped=0;function cleanName(n){return n.replace(/^[\s,;|:\-–—.•*_=~]+/,'').replace(/[\s,;|:\-–—.•*_=~…]+$/,'').replace(/\s{2,}/g,' ').trim()}function add(name,price){name=cleanName(name);price=parseFloat(price);if(!/[A-Za-z]{2}/.test(name)||!(price>0&&price<=5000)||name.length>60){skipped++;return}var key=name.toLowerCase();if(seen[key])return;seen[key]=1;var c=categorize(name);items.push({name:name,price:price,cat:c!=='Other'?c:(ctx||'Other')})}var lines=text.split(/\r?\n/);for(var li=0;li<lines.length;li++){var line=lines[li].replace(/^\s*[•·*]\s*/,'').replace(/^\s*\d{1,2}[.)]\s+(?=[A-Za-z])/,'').replace(/[|_=~]{1,}/g,' ').trim();if(!line)continue;if(/^[A-Z][A-Z \-&]{3,}$/.test(line)&&!/\d/.test(line)){ctx=cap(line.toLowerCase());continue}var re=/\$(\d{1,4}(?:\.\d{1,2})?)/g;var ms=[],m;while((m=re.exec(line))!==null)ms.push(m);if(ms.length){var prev=0;for(var i=0;i<ms.length;i++){var before=line.slice(prev,ms[i].index);if(cleanName(before))add(before,ms[i][1]);else if(i===ms.length-1)add(line.slice(ms[i].index+ms[i][0].length),ms[i][1]);prev=ms[i].index+ms[i][0].length}continue}var b=line.match(/^(.*[A-Za-z)].*?)[\s.\-–—:…]+(\d{1,4}(?:\.\d{1,2})?)$/);if(b){add(b[1],b[2]);continue}if(line.length<35&&!/[0-9]/.test(line))ctx=cap(line.toLowerCase())}return {items:items,skipped:skipped}}
function isOpenNow(spot){if(!spot||!spot.hours)return true;var h=spot.hours.toLowerCase();if(h.indexOf('24')>-1)return true;var m=h.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)\s*[-–]\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)/);if(!m)return true;function toMin(hh,mm,ap){var hh2=+hh;if(ap==='pm'&&hh2!==12)hh2+=12;if(ap==='am'&&hh2===12)hh2=0;return hh2*60+(+mm||0)}var open=toMin(m[1],m[2],m[3]),close=toMin(m[4],m[5],m[6]);var cur=new Date().getHours()*60+new Date().getMinutes();if(close<open)return cur>=open||cur<close;return cur>=open&&cur<=close}
function cheapestFor(spot,craving){if(!spot.menu||!spot.menu.length)return null;var found=null;for(var i=0;i<CRAVINGS.length;i++){if(CRAVINGS[i].k===craving)found=CRAVINGS[i]}var re=found?found.re:null;var list=re?spot.menu.filter(function(x){return re.test(x.name)}):spot.menu;if(!list.length)return null;return Math.min.apply(null,list.map(function(x){return x.price}))}
function spotCoords(s){if(s.lat!=null&&s.lng!=null)return [s.lat,s.lng];return AREA_COORDS[s.area]||null}
function distToSpot(s){if(!STATE.near)return 999;return haversineKm(STATE.near,spotCoords(s))}
function scoreSpot(s){var sc=(s.rating||3)*20+(s.visits||0)*0.5;if(isOpenNow(s))sc+=10;return sc}
function filteredSpots(){var list=SPOTS.slice();if(STATE.q){var q=STATE.q.toLowerCase();list=list.filter(function(s){return s.name.toLowerCase().indexOf(q)>-1||s.area.toLowerCase().indexOf(q)>-1||(s.menu||[]).some(function(i){return i.name.toLowerCase().indexOf(q)>-1})})}if(STATE.area)list=list.filter(function(s){return s.area===STATE.area});if(STATE.price)list=list.filter(function(s){return String(s.price)===String(STATE.price)});if(STATE.craving){var found=null;for(var i=0;i<CRAVINGS.length;i++){if(CRAVINGS[i].k===STATE.craving)found=CRAVINGS[i]}if(found)list=list.filter(function(s){return (s.menu||[]).some(function(x){return found.re.test(x.name)})})}if(STATE.openOnly||Store.settings().openOnly)list=list.filter(isOpenNow);if(STATE.sort==='rating')list.sort(function(a,b){return b.rating-a.rating});else if(STATE.sort==='low')list.sort(function(a,b){return (cheapestFor(a,STATE.craving)||999)-(cheapestFor(b,STATE.craving)||999)});else if(STATE.sort==='near')list.sort(function(a,b){return distToSpot(a)-distToSpot(b)});else list.sort(function(a,b){return scoreSpot(b)-scoreSpot(a)});return list}
function go(view){if(document.body.classList.contains('app-minimized'))returnAppNow();if(view==='add'&&!IS_ADMIN){toast('View only - ask Wavelord to add a spot');return}STATE.view=view;$$('.view').forEach(function(v){v.classList.remove('active')});var el=$('#v-'+view);if(el)el.classList.add('active');$$('#nav button').forEach(function(b){b.classList.toggle('on',b.dataset.v===view)});window.scrollTo({top:0});if(view==='home')renderHome();if(view==='favs')renderFavs();if(view==='top10')renderTop10();if(view==='compare')fillAreaSelects();if(view==='settings')renderSettings();if(view==='vote')renderVote()}
function cardHTML(s){var open=isOpenNow(s);var cheap=cheapestFor(s,STATE.craving);var fav=Store.favs().has(s.id)?'❤️':'🤍';var d=(STATE.sort==='near'&&STATE.near)?' • '+distToSpot(s).toFixed(1)+' km':'';var hasPhotos=(s.photos&&s.photos.length)?' • 📸 '+s.photos.length+' menu photo'+(s.photos.length>1?'s':''):'';return '<div class="card" data-act="detail" data-id="'+s.id+'"><h3>'+esc(s.name)+' '+(open?'':'<span class="badge closed">Closed</span>')+' '+(s.visits>15?'<span class="badge hot">🔥 Popular</span>':'')+'</h3><div class="meta">📍 '+esc(s.area)+d+' • '+'$'.repeat(s.price)+' • ⭐ '+s.rating+hasPhotos+'</div><div class="meta">'+(cheap!=null?'From '+money(cheap)+' • ':'')+esc(s.notes||'')+' • Updated '+timeAgo(s.updated)+'</div><div class="row" style="margin-top:8px"><button class="sm" data-act="fav" data-id="'+s.id+'">'+fav+' Save</button>'+(s.photos&&s.photos.length?'<button class="sm" data-act="browseMenu" data-id="'+s.id+'">📸 Browse Menu</button>':'')+'<button class="sm primary" data-act="detail" data-id="'+s.id+'">View menu ›</button></div></div>'}
function renderHome(){var chips=$('#chips');if(chips)chips.innerHTML=CRAVINGS.map(function(c){return '<button class="chip '+(STATE.craving===c.k?'on':'')+'" data-act="crave" data-v="'+c.k+'">'+c.k+'</button>'}).join('');var fa=$('#fArea');if(fa&&!fa.dataset.done){fa.dataset.done='1';fa.innerHTML='<option value="">All areas</option>'+AREAS.map(function(a){return '<option>'+a+'</option>'}).join('')}var fy=$('#forYou');if(fy){var top=SPOTS.slice().sort(function(a,b){return scoreSpot(b)-scoreSpot(a)}).slice(0,3);fy.innerHTML='<div class="secHead"><h2>⭐ For you in Trinidad</h2></div><p class="sub">Based on ratings + visits + open now.</p>'+top.map(cardHTML).join('')}var tr=$('#trendSec');if(tr){var hot=SPOTS.slice().sort(function(a,b){return b.visits-a.visits}).slice(0,3);tr.innerHTML='<div class="sec"><div class="secHead"><h2>🔥 Trending</h2></div>'+hot.map(cardHTML).join('')+'</div>'}var t10=$('#top10Sec');if(t10){var top2=SPOTS.slice().sort(function(a,b){return b.rating-a.rating}).slice(0,3);t10.innerHTML='<div class="sec"><div class="secHead"><h2>🏆 Top rated</h2><button class="sm primary" data-act="go" data-v="top10">See Top 10</button></div>'+top2.map(cardHTML).join('')+'</div>'}var sp=$('#specialsSec');if(sp){var cheap=SPOTS.filter(function(s){var c=cheapestFor(s,'');return c!=null&&c<=65}).slice(0,3);sp.innerHTML='<div class="sec"><div class="secHead"><h2>💸 Cheap eats under $65</h2></div>'+(cheap.map(cardHTML).join('')||'<p class="sub">No cheap eats found yet - add one!</p>')+'</div>'}renderList()}
function renderList(){var list=filteredSpots();var el=$('#homeList');if(!el)return;el.innerHTML='<div class="secHead" style="margin-top:14px"><h2>'+list.length+' spot'+(list.length!==1?'s':'')+' found</h2></div>'+(list.length?list.slice(0,STATE.pageSize).map(cardHTML).join(''):'<p class="empty">Nothing found. Try another craving or area - or add the spot!</p>');var more=$('#homeMore');if(more)more.innerHTML=list.length>STATE.pageSize?'<button class="ghost" data-act="showMore">Show more</button>':'';var saved=$('#savedLine');if(saved)saved.textContent=SPOTS.length+' spots saved • '+Store.favs().size+' favourites'}
