function menuRowHTML(item){item=item||{name:'',price:'',cat:'Other'};return '<div class="row menuRow" style="margin-top:6px"><input class="mName" placeholder="Item name" value="'+esc(item.name)+'"><input class="mPrice" type="number" step="0.01" placeholder="Price" value="'+item.price+'"><select class="mCat">'+['Other'].concat(CATS).map(function(c){return '<option '+(c===item.cat?'selected':'')+'>'+c+'</option>'}).join('')+'</select><button type="button" class="sm" data-act="delMenuRow">✕</button></div>'}
function openAdd(id){if(!requireAdmin())return;$('#addForm').reset();$('#fId').value=id||'';$('#photoPrev').innerHTML='';STATE.editingPhotos=[];if(id){var s=null;for(var i=0;i<SPOTS.length;i++){if(SPOTS[i].id===id)s=SPOTS[i]}if(!s)return;$('#addTitle').textContent='Edit spot';$('#fName').value=s.name;$('#fArea2').value=s.area;$('#fAddr').value=s.addr||'';$('#fPhone').value=s.phone||'';$('#fHours').value=s.hours||'';$('#fPriceLvl').value=s.price;$('#fRating').value=s.rating;$('#fNotes').value=s.notes||'';STATE.editingPhotos=(s.photos||[]).slice();$('#photoPrev').innerHTML=STATE.editingPhotos.map(function(p){return '<img src="'+p+'" style="width:80px;height:60px;object-fit:cover;border-radius:8px">'}).join('');$('#menuRows').innerHTML=(s.menu||[]).map(menuRowHTML).join('')}else{$('#addTitle').textContent='Add a spot';$('#menuRows').innerHTML=menuRowHTML()+menuRowHTML()}go('add')}
function collectMenu(){return $$('.menuRow').map(function(r){return {name:$('.mName',r).value.trim(),price:parseFloat($('.mPrice',r).value)||0,cat:$('.mCat',r).value}}).filter(function(i){return i.name&&i.price>0}).map(function(i){return {name:i.name,price:i.price,cat:i.cat==='Other'?categorize(i.name):i.cat}})}
function appendMenuItems(newItems){var existing=collectMenu();var seen={};existing.forEach(function(i){seen[i.name.toLowerCase().trim()]=1});var added=0,skipped=0;(newItems||[]).forEach(function(item){var key=(item.name||'').toLowerCase().trim();if(!key||seen[key]){skipped++;return}seen[key]=1;var emptyRow=null;var rows=document.querySelectorAll('.menuRow');for(var i=0;i<rows.length;i++){if(!$('.mName',rows[i]).value.trim()){emptyRow=rows[i];break}}if(emptyRow){$('.mName',emptyRow).value=item.name;$('.mPrice',emptyRow).value=item.price;$('.mCat',emptyRow).value=item.cat||categorize(item.name)}else{$('#menuRows').insertAdjacentHTML('beforeend',menuRowHTML(item))}added++});return {added:added,skipped:skipped}}
function saveSpot(e){if(e)e.preventDefault();if(!requireAdmin())return;var id=$('#fId').value||uid();var coords=AREA_COORDS[$('#fArea2').value]||[10.65,-61.44];var spot={id:id,name:$('#fName').value.trim(),area:$('#fArea2').value,addr:$('#fAddr').value.trim(),phone:$('#fPhone').value.trim(),hours:$('#fHours').value.trim(),price:+$('#fPriceLvl').value,rating:parseFloat($('#fRating').value)||4,notes:$('#fNotes').value.trim(),menu:collectMenu(),photos:STATE.editingPhotos,created:nowISO(),updated:nowISO(),visits:0,lat:coords[0],lng:coords[1]};if(!spot.name)return toast('Add a name first');var idx=-1;for(var i=0;i<SPOTS.length;i++){if(SPOTS[i].id===id)idx=i}if(idx>=0){spot.created=SPOTS[idx].created;spot.visits=SPOTS[idx].visits;spot.lat=SPOTS[idx].lat;spot.lng=SPOTS[idx].lng;SPOTS[idx]=spot}else SPOTS.unshift(spot);Store.set('spots',SPOTS);toast('Saved! Photos will show in Browse Menu');go('home');renderHome()}
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function openPaste(){openModal('<h3>📋 Paste menu</h3><p class="sub">Paste menu text - this ADDS, never erases.</p><textarea id="pasteText" rows="8" placeholder="Beef Burger - $85\nDoubles - $12"></textarea><button class="primary" data-act="doPaste" style="margin-top:10px">Parse & add menu</button><p class="sub" id="pasteMsg"></p>')}
function openScan(){openModal('<h3>📸 Scan menu</h3><p class="sub">Take photos of a menu - each scan ADDS, never erases.</p><input type="file" id="scanFile" accept="image/*" multiple><button class="primary" data-act="doScan" style="margin-top:10px">Scan & add to menu</button><p class="sub" id="scanMsg"></p>')}
async function doScan(){var files=[];var inp=$('#scanFile');if(inp)files=Array.prototype.slice.call(inp.files||[]);if(!files.length)return toast('Pick a photo first');$('#scanMsg').textContent='Reading '+files.length+' photo(s)...';try{if(!window.Tesseract){await new Promise(function(res,rej){var s=document.createElement('script');s.src=APP.ocrCdn;s.onload=res;s.onerror=rej;document.head.appendChild(s)})}var totalAdded=0,totalSkipped=0;for(var i=0;i<files.length;i++){$('#scanMsg').textContent='Reading photo '+(i+1)+' of '+files.length+'...';var result=await Tesseract.recognize(files[i],'eng');var parsed=parseMenuText(result.data.text,{ocr:true});var res=appendMenuItems(parsed.items);totalAdded+=res.added;totalSkipped+=res.skipped}closeModal();toast('Added '+totalAdded+' new items - old menu kept')}catch(e){Store.logError(e);$('#scanMsg').textContent='Scan failed: '+e.message}}
function runCompare(){var craving=$('#cCrave').value,area=$('#cArea').value;var list=SPOTS.filter(function(s){return !area||s.area===area}).map(function(s){return {s:s,cheap:cheapestFor(s,craving)}}).filter(function(x){return x.cheap!=null}).sort(function(a,b){return a.cheap-b.cheap});$('#compareOut').innerHTML=list.length?'<div class="sec"><h3>Best value - '+craving+' '+(area?'in '+area:'')+'</h3><table><tr><th>Spot</th><th>Area</th><th>Cheapest</th><th>Rating</th></tr>'+list.map(function(x){return '<tr><td>'+esc(x.s.name)+'</td><td>'+esc(x.s.area)+'</td><td>'+money(x.cheap)+'</td><td>⭐ '+x.s.rating+'</td></tr>'}).join('')+'</table></div>':'<p class="empty">No spots match that craving yet.</p>'}
function renderTop10(){fillAreaSelects();var cat=$('#tCat')?$('#tCat').value:'';var list=SPOTS.slice();if(cat)list=list.filter(function(s){return (s.menu||[]).some(function(i){return i.cat===cat})});list=list.sort(function(a,b){return b.rating-a.rating}).slice(0,10);$('#top10Out').innerHTML=list.length?list.map(function(s,i){return '<div class="card" data-act="detail" data-id="'+s.id+'"><h3>#'+(i+1)+' '+esc(s.name)+'</h3><div class="meta">'+esc(s.area)+' • ⭐ '+s.rating+' • '+'$'.repeat(s.price)+'</div></div>'}).join(''):'<p class="empty">No spots yet.</p>'}
function runBudget(){var total=+$('#bTotal').value||200,people=+$('#bPeople').value||2,per=total/people;var fits=SPOTS.map(function(s){return {s:s,cheap:cheapestFor(s,'')}}).filter(function(x){return x.cheap!=null&&x.cheap<=per}).sort(function(a,b){return a.cheap-b.cheap});$('#budgetOut').innerHTML='<div class="sec"><p><b>$'+total+' for '+people+' people = '+money(per)+' each.</b></p>'+(fits.length?fits.map(function(x){return '<div class="card" data-act="detail" data-id="'+x.s.id+'"><h3>'+esc(x.s.name)+'</h3><div class="meta">'+esc(x.s.area)+' • From '+money(x.cheap)+'</div></div>'}).join(''):'<p class="sub">Nothing fits that budget - try raising it a bit.</p>')+'</div>'}
function renderFavs(){var favs=SPOTS.filter(function(s){return Store.favs().has(s.id)});$('#favOut').innerHTML=favs.length?favs.map(cardHTML).join(''):'<p class="empty">No favourites yet - tap 🤍 on a spot to save it.</p>'}
function renderSettings(){var st=Store.settings();var big=$('#sBigText');if(big)big.checked=!!st.bigText;var open=$('#sOpenOnly');if(open)open.checked=!!st.openOnly;var pa=$('#sPriceAlert');if(pa)pa.checked=!!st.priceAlert}
function renderAdmin(){var body=$('#adminBody');if(!body)return;body.innerHTML='<div class="sec"><h3>Spots ('+SPOTS.length+')</h3>'+SPOTS.map(function(s){return '<div class="row" style="justify-content:space-between;border-bottom:1px solid var(--line);padding:8px 0"><span>'+esc(s.name)+' • '+esc(s.area)+'</span><span><button class="sm" data-act="edit" data-id="'+s.id+'">Edit</button> <button class="sm" data-act="deleteSpot" data-id="'+s.id+'">Delete</button></span></div>'}).join('')+'</div><div class="sec"><h3>Errors ('+Store.errors().length+')</h3><p class="sub">'+(Store.errors().slice(0,5).map(function(e){return esc(e.msg)}).join('<br>')||'No errors')+'</p></div>'}
function buildVoteLink(){ensureVoteShape();var q=$('#vQ')?$('#vQ').value.trim()||STATE.vote.q:STATE.vote.q;STATE.vote.q=q;if(!STATE.vote.opts.length)return null;var payload={id:STATE.vote.id,q:STATE.vote.q,opts:STATE.vote.opts,votes:STATE.vote.votes};var encoded=btoa(unescape(encodeURIComponent(JSON.stringify(payload))));return location.origin+location.pathname+'?vote='+encodeURIComponent(encoded)}
function loadVoteFromURL(){try{var p=new URLSearchParams(location.search);var v=p.get('vote');if(!v)return false;var decoded=decodeURIComponent(escape(atob(decodeURIComponent(v))));var j=JSON.parse(decoded);if(!j.opts||!j.opts.length)return false;STATE.vote.id=j.id||('vote_'+uid());STATE.vote.q=j.q||'What we eating tonight?';STATE.vote.opts=j.opts;STATE.vote.votes=j.votes||{};STATE.vote.myVotes={};ensureVoteShape();loadMyVote();STATE.sharedVote=true;return true}catch(e){return false}}
async function shareVote(){if(!STATE.vote.opts.length){toast('Add at least 1 option first');return}var link=buildVoteLink();if(!link)return;var box=$('#voteLinkBox');var input=$('#voteLinkInput');if(input)input.value=link;if(box)box.classList.remove('hidden');var msgEl=$('#voteShareMsg');if(msgEl)msgEl.textContent='Link ready - 1 vote per person per option. Guest votes, then taps Copy Updated Link to send counts back.';renderVote();try{if(navigator.share){await navigator.share({title:STATE.vote.q,text:'Vote: '+STATE.vote.q,url:link})}else{await navigator.clipboard.writeText(link);toast('Link copied')}}catch(e){try{await navigator.clipboard.writeText(link);toast('Link copied')}catch(e2){toast('Long-press the link below to copy it')}}}
async function copyVoteLink(){var input=$('#voteLinkInput');var link=(input&&input.value)||buildVoteLink();if(!link){toast('Add options first');return}try{await navigator.clipboard.writeText(link);toast('Link copied')}catch(e){if(input)input.select();document.execCommand('copy');toast('Link copied')}}
async function copyUpdatedVoteLink(){var link=buildVoteLink();if(!link){toast('Add options first');return}var input=$('#voteLinkInput');if(input)input.value=link;try{await navigator.clipboard.writeText(link);toast('Updated link copied - send it back to the group')}catch(e){if(input)input.select();document.execCommand('copy');toast('Updated link copied')}}
function openVoteWhatsApp(){var link=($('#voteLinkInput')&&$('#voteLinkInput').value)||buildVoteLink();if(!link){toast('Add options first');return}window.open('https://wa.me/?text='+encodeURIComponent('Vote: '+STATE.vote.q+' - Tap the link and vote 👍 / 👎 - '+link),'_blank')}
function doVote(opt,dir){ensureVoteShape();var prev=STATE.vote.myVotes[opt]||null;var cur=STATE.vote.votes[opt]||{up:0,down:0};if(prev===dir){if(dir==='up')cur.up=Math.max(0,cur.up-1);else cur.down=Math.max(0,cur.down-1);STATE.vote.myVotes[opt]=null;toast('Vote removed for '+opt)}else{if(prev==='up')cur.up=Math.max(0,cur.up-1);if(prev==='down')cur.down=Math.max(0,cur.down-1);if(dir==='up')cur.up++;else cur.down++;STATE.vote.myVotes[opt]=dir;toast((dir==='up'?'👍':'👎')+' Voted for '+opt+' — tap Copy Updated Link to send counts back')}STATE.vote.votes[opt]=cur;saveMyVote();var inp=$('#voteLinkInput');if(inp)inp.value=buildVoteLink()||'';renderVote()}
function renderVote(){ensureVoteShape();var vQ=$('#vQ');if(vQ&&STATE.vote.q)vQ.value=STATE.vote.q;var optsEl=$('#voteOpts');if(optsEl)optsEl.innerHTML=STATE.vote.opts.map(function(o){return '<span class="chip">'+esc(o)+'</span>'}).join('');var out=$('#voteOut');if(!out)return;var sorted=STATE.vote.opts.slice().sort(function(a,b){var va=STATE.vote.votes[a]||{up:0,down:0},vb=STATE.vote.votes[b]||{up:0,down:0};return (vb.up-vb.down)-(va.up-va.down)});var topNet=sorted.length?((STATE.vote.votes[sorted[0]]||{up:0,down:0}).up-(STATE.vote.votes[sorted[0]]||{up:0,down:0}).down):0;out.innerHTML='<div class="sec"><h3>'+esc(STATE.vote.q)+'</h3>'+(STATE.sharedVote?'<p class="sub">Shared vote — 1 vote per person per option. Tap 👍 or 👎 once. Tap again to undo. Then Copy Updated Link.</p>':'<p class="sub">Tap 👍 if yuh want it, 👎 if yuh doh want it. 1 vote per person per option. Winner = highest net score.</p>')+STATE.vote.opts.map(function(o){var v=STATE.vote.votes[o]||{up:0,down:0};var net=v.up-v.down;var isWin=sorted.length&&o===sorted[0]&&topNet>0;var my=STATE.vote.myVotes[o]||null;return '<div class="voteRow"><div class="row" style="justify-content:space-between"><b>'+esc(o)+(isWin?' <span class="badge win">🏆 Winning</span>':'')+'</b><span>👍 '+v.up+' • 👎 '+v.down+' • Net: '+(net>0?'+':'')+net+(my?' • You voted '+(my==='up'?'👍':'👎'):'')+'</span></div><div class="row" style="margin-top:8px"><button class="sm up '+(my==='up'?'voted':'')+'" data-act="voteUp" data-v="'+esc(o)+'">👍 Vote Up</button><button class="sm down '+(my==='down'?'voted':'')+'" data-act="voteDown" data-v="'+esc(o)+'">👎 Vote Down</button></div></div>'}).join('')+'</div>'}
function buddyToggle(){var b=$('#buddy');if(!b)return;var willOpen=b.classList.contains('hidden');b.classList.toggle('hidden');if(willOpen){var m=$('#buddyMenu');if(m)m.classList.add('hidden');if(!$('#buddyMsgs').dataset.done){$('#buddyMsgs').dataset.done='1';buddySay('Wah yuh feeling for? 🍔\nAsk me anything — food in the app, or anything else. Try "cheap doubles", "etymology of sonder", or tap 🎤 and talk.')}}}
function buddySay(text){var box=$('#buddyMsgs');if(!box)return;var d=document.createElement('div');d.className='msg bot';d.textContent=text;box.appendChild(d);box.scrollTop=box.scrollHeight}
function buddySayHTML(html){var box=$('#buddyMsgs');if(!box)return;var d=document.createElement('div');d.className='msg bot';d.innerHTML=html;box.appendChild(d);box.scrollTop=box.scrollHeight}
function buddySayResults(title,list){var html='<b>'+esc(title)+'</b>'+list.map(function(s,i){return '<div style="margin-top:8px"><b>'+(i+1)+'. '+esc(s.name)+'</b><br>'+esc(s.area)+' • From '+money(cheapestFor(s,'')||0)+' • ⭐ '+s.rating+' • '+(isOpenNow(s)?'Open now':'Closed')+'<br><button class="sm primary" data-act="detail" data-id="'+s.id+'">View menu ›</button></div>'}).join('');buddySayHTML(html)}
function isGeneralQuestion(lower){return lower.indexOf('etymology')>-1||lower.indexOf('meaning of')>-1||lower.indexOf('define')>-1||lower.indexOf('definition')>-1||lower.indexOf('what is')>-1||lower.indexOf('who is')>-1||lower.indexOf('capital of')>-1||lower.indexOf('why')>-1||lower.indexOf('sonder')>-1||lower.indexOf('explain')>-1}
function isAppQuestion(lower){if(isGeneralQuestion(lower)&&lower.indexOf('voting')===-1&&lower.indexOf('vote')===-1&&lower.indexOf('compare')===-1&&lower.indexOf('budget')===-1)return false;return lower.indexOf('doubles')>-1||lower.indexOf('roti')>-1||lower.indexOf('burger')>-1||lower.indexOf('pizza')>-1||lower.indexOf('chicken')>-1||lower.indexOf('seafood')>-1||lower.indexOf('shark')>-1||lower.indexOf('cheap')>-1||lower.indexOf('open now')>-1||lower.indexOf('best')>-1||lower.indexOf('top')>-1||lower.indexOf('compare')>-1||lower.indexOf('budget')>-1||lower.indexOf('vote')>-1||lower.indexOf('voting')>-1||lower.indexOf('favourite')>-1||lower.indexOf('favorite')>-1||lower.indexOf('add')>-1||lower.indexOf('spot')>-1||lower.indexOf('near me')>-1||lower.indexOf('tunapuna')>-1||lower.indexOf('san juan')>-1||lower.indexOf('chaguanas')>-1||lower.indexOf('what we eating')>-1||lower.indexOf('wavelord')>-1}
function appAnswer(q,lower){if(lower.indexOf('how does voting work')>-1||lower.indexOf('how voting')>-1||lower.indexOf('how do i vote')>-1){return 'Voting is easy:\n1. Go to 🗳️ Vote tab\n2. Type question + Add options (e.g. Doubles, Roti)\n3. Tap Start vote, then Share vote link\n4. Family opens link and taps 👍 Vote Up or 👎 Vote Down — 1 vote per person per option\n5. Winner = highest net score. Guest taps Copy Updated Link to send counts back.'}
if(lower.indexOf('compare')>-1&&lower.indexOf('how')>-1){return 'Compare = pick a craving + area, tap Compare. It shows cheapest to most expensive in a table so yuh see best value before yuh spend.'}
if(lower.indexOf('budget')>-1&&lower.indexOf('how')>-1){return 'Budget Lime: Go to 💰 Budget, put total money + how many people. It shows spots where cheapest item fits per person.'}
if(lower.indexOf('add')>-1&&lower.indexOf('spot')>-1){return 'To add a spot: Settings → Admin → password 1919 → Add tab. Then fill name, area, menu + menu photos. Guests stay view-only.'}
if(lower.indexOf('open now')>-1||lower.indexOf('still open')>-1){var openList=SPOTS.filter(isOpenNow);if(!openList.length)return 'Nothing showing as open right now in our list.';return 'Open now:\n'+openList.slice(0,5).map(function(s,i){return (i+1)+'. '+s.name+' - '+s.area+' - From '+money(cheapestFor(s,'')||0)}).join('\n')}
if(lower.indexOf('wavelord')>-1){return 'Wavelord is the creator of What We Eating? — Trinidad & Tobago food lime finder. 🍔'}
return null}
async function buddyAskGroq(q){try{var spotsCtx='SPOTS:\n'+SPOTS.slice(0,20).map(function(s){return '- '+s.name+' in '+s.area+' | ⭐ '+s.rating+' | '+'$'.repeat(s.price)+' | Hours: '+(s.hours||'n/a')+' | Menu: '+(s.menu||[]).map(function(i){return i.name+' $'+i.price}).join(', ')}).join('\n');var res=await fetch((location.protocol==='file:'?APP.siteUrl:'')+APP.fnBase+'/groq-chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[{role:'user',content:q}],context:spotsCtx,spots:SPOTS.slice(0,20).map(function(s){return {name:s.name,area:s.area,rating:s.rating,price:s.price,hours:s.hours,menu:s.menu}})})});if(!res.ok)throw new Error('groq failed '+res.status);var j=await res.json();return j.text||j.reply||j.answer||null}catch(e){Store.logError(e);return null}}
function buddyLocalFallback(q,lower){if(lower.indexOf('sonder')>-1)return 'Sonder — etymology + meaning:\nSonder is a modern word coined by John Koenig in The Dictionary of Obscure Sorrows (2012). It is not from Latin/Greek — Koenig made it up.\nMeaning: the realization that each random passerby is living a life as vivid and complex as your own.';
if(lower.indexOf('etymology')>-1||lower.indexOf('meaning of')>-1)return 'Good question! I tried to reach my smart brain (Groq) but it is offline right now. Try again in a sec.';
if(lower.indexOf('capital')>-1&&lower.indexOf('france')>-1)return 'The capital of France is Paris.';
if(lower.indexOf('capital')>-1&&lower.indexOf('trinidad')>-1)return 'The capital of Trinidad and Tobago is Port of Spain.';
if(lower.indexOf('who are you')>-1||lower.indexOf('your name')>-1)return 'I am Wave Buddy 🍔 — inside What We Eating? by Wavelord. I find food in Trinidad & Tobago, and I can answer general questions too. Ask me anything!';
if(lower.indexOf('hello')>-1||lower.indexOf('hi')>-1||lower==='hey'||lower==='yo')return 'Hey! 👋 Wah yuh feeling for? Try "cheap doubles", "best roti in Tunapuna", or ask me anything else.';
if(lower.indexOf('thank')>-1)return 'Anytime! Enjoy yuh lime 😋';
return 'Good question! My smart brain (Groq) is offline right now. Try again in a sec, or ask me about food — like "cheap doubles", "best roti in Tunapuna", "what is open now?", "how does voting work?"'}
async function buddySend(text){var input=$('#buddyText');var q=(text||(input&&input.value)||'').trim();if(!q)return;var box=$('#buddyMsgs');if(box){var me=document.createElement('div');me.className='msg me';me.textContent=q;box.appendChild(me);box.scrollTop=box.scrollHeight}if(input)input.value='';var lower=q.toLowerCase().trim();if(/^(hi|hey|hello|yo|wassup|good (morning|afternoon|evening))$/.test(lower)){buddySay('Hey! 👋 Wah yuh feeling for? Try "cheap doubles", "best roti in Tunapuna", "pizza", or "what is open now?"');return}if(lower.indexOf('thank')>-1){buddySay('Anytime! Enjoy yuh lime 😋');return}if(lower.indexOf('help')>-1){buddySay('Try: "cheap doubles", "best roti in Tunapuna", "what is open now?", "cheapest burger", "best rated", or ask anything like "etymology of sonder"');return}var hard=appAnswer(q,lower);if(hard){buddySay(hard);return}
if(isAppQuestion(lower)){var areaFound=null;for(var ai=0;ai<AREAS.length;ai++){if(lower.indexOf(AREAS[ai].toLowerCase())>-1){areaFound=AREAS[ai];break}}var cravingFound=null;for(var ci=0;ci<CRAVINGS.length;ci++){if(CRAVINGS[ci].re.test(lower)){cravingFound=CRAVINGS[ci];break}}var wantsOpen=lower.indexOf('open now')>-1||lower.indexOf('still open')>-1;var wantsCheap=lower.indexOf('cheap')>-1||lower.indexOf('cheapest')>-1;var wantsBest=lower.indexOf('best')>-1||lower.indexOf('top')>-1||lower.indexOf('rated')>-1;var list=SPOTS.slice();if(areaFound)list=list.filter(function(s){return s.area===areaFound});if(cravingFound)list=list.filter(function(s){return (s.menu||[]).some(function(i){return cravingFound.re.test(i.name)})||s.name.toLowerCase().indexOf(cravingFound.k.toLowerCase())>-1});if(wantsOpen)list=list.filter(isOpenNow);if(wantsCheap)list.sort(function(a,b){return (cheapestFor(a,cravingFound?cravingFound.k:'')||999)-(cheapestFor(b,cravingFound?cravingFound.k:'')||999)});else if(wantsBest)list.sort(function(a,b){return b.rating-a.rating});else list.sort(function(a,b){return scoreSpot(b)-scoreSpot(a)});if(!list.length){buddySay('Nothing found '+(areaFound?'in '+areaFound:'')+' '+(cravingFound?'for '+cravingFound.k:'')+'. Try another area or craving.');return}buddySayResults('Top picks '+(cravingFound?cravingFound.k:'')+' '+(areaFound?'in '+areaFound:''),list.slice(0,3));return}
var typing=document.createElement('div');typing.className='msg bot typing';typing.textContent='Buddy is thinking...';if(box)box.appendChild(typing);var reply=await buddyAskGroq(q);if(typing)typing.remove();if(reply){buddySay(reply)}else{buddySay(buddyLocalFallback(q,lower))}}
function roulette(){var open=SPOTS.filter(isOpenNow);var pool=open.length?open:SPOTS;var pick=pool[Math.floor(Math.random()*pool.length)];if(!pick)return;$('#rouletteTitle').textContent='🎲 '+pick.name;$('#rouletteText').textContent=pick.area+' • From '+money(cheapestFor(pick,'')||0)+' • ⭐ '+pick.rating;$('#rouletteBox').classList.remove('hidden')}
function doNearMe(){if(!('geolocation' in navigator)){toast('Location not available');return}toast('Finding your location…');navigator.geolocation.getCurrentPosition(function(pos){STATE.near=[pos.coords.latitude,pos.coords.longitude];STATE.sort='near';var fs=$('#fSort');if(fs)fs.value='near';renderHome();toast('Sorted by nearest to you')},function(){STATE.near=[10.65,-61.44];STATE.sort='near';var fs=$('#fSort');if(fs)fs.value='near';renderHome();toast('Location blocked - using San Juan')},{timeout:8000})}
function positionBuddyMenu(){var fab=$('#buddyFab');var menu=$('#buddyMenu');if(!fab||!menu)return;var r=fab.getBoundingClientRect();var mw=220,mh=220;var left=r.left+70;if(left+mw>window.innerWidth-8)left=r.left-mw-8;if(left<8)left=8;var top=r.top;if(top+mh>window.innerHeight-8)top=window.innerHeight-mh-8;if(top<8)top=8;menu.style.left=left+'px';menu.style.top=top+'px';menu.style.right='auto';menu.style.bottom='auto'}
function positionBuddyChat(){var fab=$('#buddyFab');var chat=$('#buddy');if(!fab||!chat)return;var r=fab.getBoundingClientRect();var cw=Math.min(380,window.innerWidth-28);var left=r.left+70;if(left+cw>window.innerWidth-8)left=r.left-cw-8;if(left<14)left=14;var top=r.top-360;if(top<8)top=8;chat.style.left=left+'px';chat.style.top=top+'px';chat.style.right='auto';chat.style.bottom='auto'}
var FAB_DRAG={active:false,moved:false,startX:0,startY:0,origLeft:0,origTop:0};
function fabStart(e){var fab=$('#buddyFab');if(!fab)return;var p=e.touches?e.touches[0]:e;FAB_DRAG.active=true;FAB_DRAG.moved=false;FAB_DRAG.startX=p.clientX;FAB_DRAG.startY=p.clientY;var r=fab.getBoundingClientRect();FAB_DRAG.origLeft=r.left;FAB_DRAG.origTop=r.top;fab.classList.add('dragging')}
function fabMove(e){if(!FAB_DRAG.active)return;var p=e.touches?e.touches[0]:e;var dx=p.clientX-FAB_DRAG.startX,dy=p.clientY-FAB_DRAG.startY;if(Math.abs(dx)>6||Math.abs(dy)>6)FAB_DRAG.moved=true;if(!FAB_DRAG.moved)return;if(e.cancelable)e.preventDefault();var fab=$('#buddyFab');var size=64;var nx=Math.max(4,Math.min(window.innerWidth-size-4,FAB_DRAG.origLeft+dx));var ny=Math.max(4,Math.min(window.innerHeight-size-4,FAB_DRAG.origTop+dy));fab.style.left=nx+'px';fab.style.top=ny+'px';fab.style.right='auto';fab.style.bottom='auto'}
function fabEnd(e){var fab=$('#buddyFab');if(!fab||!FAB_DRAG.active)return;FAB_DRAG.active=false;fab.classList.remove('dragging');if(FAB_DRAG.moved){try{localStorage.setItem('wwe_fabPos',JSON.stringify({left:fab.style.left,top:fab.style.top}))}catch(_){}return}if(document.body.classList.contains('app-minimized')){returnAppNow();return}var menu=$('#buddyMenu');if(menu){if(menu.classList.contains('hidden')){positionBuddyMenu();menu.classList.remove('hidden')}else{menu.classList.add('hidden')}}}
function restoreFabPos(){try{var raw=localStorage.getItem('wwe_fabPos');if(!raw)return;var j=JSON.parse(raw);var fab=$('#buddyFab');if(!fab||!j.left)return;fab.style.left=j.left;fab.style.top=j.top;fab.style.right='auto';fab.style.bottom='auto'}catch(_){}}
var VOICE={rec:null,chunks:[],recording:false,stream:null};
function setVoiceStatus(t){var el=$('#buddyVoiceStatus');if(el)el.textContent=t||''}
function blobToBase64(blob){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){res(String(r.result).split(',')[1]||'')};r.onerror=rej;r.readAsDataURL(blob)})}
async function sendVoiceToWhisper(blob){try{setVoiceStatus('Transcribing your voice...');var b64=await blobToBase64(blob);var res=await fetch((location.protocol==='file:'?APP.siteUrl:'')+APP.fnBase+'/transcribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({audio:b64,mime:blob.type||'audio/webm'})});var j=await res.json().catch(function(){return{}});if(!res.ok)throw new Error(j.error||j.detail||'Transcribe failed');return (j.text||'').trim()}catch(e){Store.logError(e);setVoiceStatus('');toast('Voice failed: '+e.message);return''}}
async function toggleBuddyMic(){var btn=$('#buddyMic');if(VOICE.recording&&VOICE.rec){try{VOICE.rec.stop()}catch(e){}return}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){toast('Voice not supported on this browser - type instead');return}try{VOICE.stream=await navigator.mediaDevices.getUserMedia({audio:true});var mime='audio/webm';if(window.MediaRecorder&&MediaRecorder.isTypeSupported&&!MediaRecorder.isTypeSupported(mime))mime='';VOICE.chunks=[];VOICE.rec=mime?new MediaRecorder(VOICE.stream,{mimeType:mime}):new MediaRecorder(VOICE.stream);VOICE.rec.ondataavailable=function(e){if(e.data&&e.data.size)VOICE.chunks.push(e.data)};VOICE.rec.onstop=async function(){VOICE.recording=false;if(btn)btn.classList.remove('rec');if(VOICE.stream)VOICE.stream.getTracks().forEach(function(t){t.stop()});setVoiceStatus('');if(!VOICE.chunks.length){toast('No voice heard - try again');return}var blob=new Blob(VOICE.chunks,{type:VOICE.rec.mimeType||'audio/webm'});var text=await sendVoiceToWhisper(blob);if(text){var inp=$('#buddyText');if(inp)inp.value=text;setVoiceStatus('You said: "'+text+'" - Buddy answering...');buddySend(text);setTimeout(function(){setVoiceStatus('')},2500)}else{toast('Did not catch that - try again')}};VOICE.recording=true;if(btn)btn.classList.add('rec');setVoiceStatus('🎤 Listening... tap 🎤 again to stop (max ~10 sec)');VOICE.rec.start();setTimeout(function(){if(VOICE.recording&&VOICE.rec){try{VOICE.rec.stop()}catch(e){}}},10000)}catch(e){setVoiceStatus('');toast('Mic blocked - allow microphone in browser settings, or type instead')}}
document.addEventListener('click',function(e){var btn=e.target.closest?e.target.closest('[data-act]'):null;if(!btn)return;var act=btn.dataset.act,id=btn.dataset.id,v=btn.dataset.v;
if(act==='go'){go(v);return}
if(act==='detail'){renderDetail(id);return}
if(act==='browseMenu'){renderDetail(id);return}
if(act==='openPhoto'){openPhotoViewer(id,parseInt(btn.dataset.idx||'0',10));return}
if(act==='closePhoto'){$('#photoViewer').classList.add('hidden');return}
if(act==='photoPrev'){STATE.photoIdx=(STATE.photoIdx-1+STATE.photoList.length)%STATE.photoList.length;updatePhotoViewer();return}
if(act==='photoNext'){STATE.photoIdx=(STATE.photoIdx+1)%STATE.photoList.length;updatePhotoViewer();return}
if(act==='fav'){var added=Store.toggleFav(id);toast(added?'Saved ❤️':'Removed');renderHome();if(STATE.view==='favs')renderFavs();if(STATE.view==='detail')renderDetail(id);return}
if(act==='crave'){STATE.craving=STATE.craving===v?'':v;renderHome();return}
if(act==='showMore'){STATE.pageSize+=10;renderHome();return}
if(act==='toggleOpen'){STATE.openOnly=!STATE.openOnly;$('#openBtn').classList.toggle('on',STATE.openOnly);renderHome();return}
if(act==='nearMe'){doNearMe();return}
if(act==='edit'){openAdd(id);return}
if(act==='deleteSpot'){if(!requireAdmin())return;if(confirm('Delete this spot?')){SPOTS=SPOTS.filter(function(s){return s.id!==id});Store.set('spots',SPOTS);renderAdmin();toast('Deleted')}return}
if(act==='share'){var s=null;for(var i=0;i<SPOTS.length;i++){if(SPOTS[i].id===id)s=SPOTS[i]}if(!s)return;var txt=s.name+' in '+s.area+' - What We Eating? by Wavelord';if(navigator.share)navigator.share({title:s.name,text:txt,url:location.href}).catch(function(){});else{try{navigator.clipboard.writeText(txt)}catch(_){}}toast('Share ready');return}
if(act==='addMenuRow'){$('#menuRows').insertAdjacentHTML('beforeend',menuRowHTML());return}
if(act==='delMenuRow'){var r=btn.closest('.menuRow');if(r)r.remove();return}
if(act==='scanOpen'){openScan();return}
if(act==='pasteOpen'){openPaste();return}
if(act==='voiceOpen'){openModal('<h3>🎤 Voice</h3><p class="sub">Use 🎤 inside Wave Buddy to talk to AI. For adding spots, use Paste or Scan for now.</p>');return}
if(act==='doPaste'){var txt=$('#pasteText').value||'';var parsed=parseMenuText(txt,{});var res=appendMenuItems(parsed.items);$('#pasteMsg').textContent='Added '+res.added+' items - old menu kept ('+res.skipped+' skipped)';return}
if(act==='doScan'){doScan();return}
if(act==='closeModal'){closeModal();return}
if(act==='runCompare'){runCompare();return}
if(act==='runBudget'){runBudget();return}
if(act==='addVoteOpt'){var inp=$('#vOpt');var val=(inp.value||'').trim();if(!val)return;STATE.vote.q=$('#vQ').value.trim()||STATE.vote.q;STATE.vote.opts.push(val);ensureVoteShape();inp.value='';renderVote();return}
if(act==='voteUp'){doVote(v,'up');return}
if(act==='voteDown'){doVote(v,'down');return}
if(act==='voteFor'){doVote(v,'up');return}
if(act==='startVote'){STATE.vote.q=$('#vQ').value.trim()||STATE.vote.q;ensureVoteShape();renderVote();toast('Vote started - now tap Share vote link');return}
if(act==='shareVote'){shareVote();return}
if(act==='copyVoteLink'){copyVoteLink();return}
if(act==='copyUpdatedVoteLink'){copyUpdatedVoteLink();return}
if(act==='openVoteWhatsApp'){openVoteWhatsApp();return}
if(act==='submitClaim'){$('#claimMsg').textContent='Claim received - Wavelord will check it. Thanks!';return}
if(act==='showTutorial'){var ob=$('#onboard');if(ob)ob.classList.add('show');return}
if(act==='exportBackup'){var blob=new Blob([JSON.stringify({spots:SPOTS,exported:nowISO()},null,2)],{type:'application/json'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='what-we-eating-backup.json';a.click();return}
if(act==='importBackup'){$('#importFile').click();return}
if(act==='reportProblem'){openModal('<h3>🐛 Report a problem</h3><p class="sub">Send to '+APP.ownerEmail+'</p><textarea rows="6">'+esc(Store.errors().slice(0,5).map(function(e){return e.msg}).join('\n')||'No errors logged')+'</textarea>');return}
if(act==='adminLogin'){var pass=$('#adminPass').value;if(pass===APP.adminPassword){setAdmin(true);$('#adminLogin').classList.add('hidden');$('#adminBody').classList.remove('hidden');renderAdmin()}else toast('Wrong password');return}
if(act==='adminLogout'){setAdmin(false);go('home');return}
if(act==='buddyToggle'){buddyToggle();return}
if(act==='buddySend'){buddySend();return}
if(act==='buddyMic'){toggleBuddyMic();return}
if(act==='buddyQuick'){buddySend(v);return}
if(act==='buddyMenuTalk'){var mm=$('#buddyMenu');if(mm)mm.classList.add('hidden');if(document.body.classList.contains('app-minimized'))returnAppNow();positionBuddyChat();buddyToggle();return}
if(act==='buddyMenuMin'){minimizeAppNow();toast('App minimized — drag 🍔 anywhere');return}
if(act==='buddyMenuExit'){minimizeAppNow();toast('Exited — tap 🍔 to return');return}
if(act==='buddyMenuReturn'){returnAppNow();toast('Welcome back!');return}
if(act==='buddyMenuClose'){var mm2=$('#buddyMenu');if(mm2)mm2.classList.add('hidden');return}
if(act==='roulette'){roulette();return}
if(act==='rouletteSpin'){roulette();return}
if(act==='rouletteClose'){$('#rouletteBox').classList.add('hidden');return}
});
document.addEventListener('DOMContentLoaded',function(){try{document.body.classList.toggle('is-admin',IS_ADMIN);fillAreaSelects();renderHome();renderSettings();restoreFabPos();var fab=$('#buddyFab');if(fab){fab.addEventListener('pointerdown',fabStart);fab.addEventListener('touchstart',fabStart,{passive:true})}document.addEventListener('pointermove',fabMove);document.addEventListener('touchmove',fabMove,{passive:false});document.addEventListener('pointerup',fabEnd);document.addEventListener('touchend',fabEnd);document.addEventListener('pointercancel',fabEnd);var cameFromVoteLink=loadVoteFromURL();var q=$('#q');if(q)q.addEventListener('input',function(){STATE.q=q.value.trim();renderList()});var fa=$('#fArea');if(fa)fa.addEventListener('change',function(){STATE.area=fa.value;renderHome()});var fp=$('#fPrice');if(fp)fp.addEventListener('change',function(){STATE.price=fp.value;renderHome()});var fs=$('#fSort');if(fs)fs.addEventListener('change',function(){STATE.sort=fs.value;if(fs.value==='near'&&!STATE.near)doNearMe();else renderHome()});var addForm=$('#addForm');if(addForm)addForm.addEventListener('submit',saveSpot);var tc=$('#tCat');if(tc)tc.addEventListener('change',renderTop10);var buddyText=$('#buddyText');if(buddyText)buddyText.addEventListener('keydown',function(e){if(e.key==='Enter')buddySend()});var sBig=$('#sBigText');if(sBig)sBig.addEventListener('change',function(){Store.saveSettings({bigText:sBig.checked});renderSettings()});var sOpen=$('#sOpenOnly');if(sOpen)sOpen.addEventListener('change',function(){Store.saveSettings({openOnly:sOpen.checked});renderHome()});var imp=$('#importFile');if(imp)imp.addEventListener('change',function(e){var f=e.target.files[0];if(!f)return;var r=new FileReader();r.onload=function(){try{var j=JSON.parse(r.result);if(j.spots){SPOTS=j.spots;Store.set('spots',SPOTS);renderHome();toast('Backup restored')}}catch(err){toast('Restore failed')}};r.readAsText(f)});var fPhotos=$('#fPhotos');if(fPhotos)fPhotos.addEventListener('change',function(){var files=Array.prototype.slice.call(fPhotos.files).slice(0,APP.maxPhotos);STATE.editingPhotos=[];$('#photoPrev').innerHTML='';files.forEach(function(f){var reader=new FileReader();reader.onload=function(){STATE.editingPhotos.push(reader.result);$('#photoPrev').insertAdjacentHTML('beforeend','<img src="'+reader.result+'" style="width:80px;height:60px;object-fit:cover;border-radius:8px">')};reader.readAsDataURL(f)})});if(cameFromVoteLink){setTimeout(function(){var s=document.getElementById('splash');if(s)s.style.display='none';go('vote');renderVote();toast('Shared vote loaded - tap 👍 / 👎 to vote')},300)}}catch(err){console.log(err);toast('App loaded with a small error - splash still works')}});
